source.bookSourceComment:
//20240204修复封面接口By_zhbyjm7783
//By_Thomas喲
// 常量
_path = {
    DownApp: "/h5/download",
    GetHost: "/api/config-hosts"
};
setv = (json) => source.setVariable(JSON.stringify(json, null, "\t"));
try {
    _ = JSON.parse(source.getVariable());
} catch (err) {
    _ = {
        time: 20240201,
        url: [
"https://103.183.155.64#dns#",
"https://novel-api.xiaoshuottaa.com",
"https://novel-api.xiaoxiaommkk.com",
"https://novel-api.xiaoppkk.com",
"https://novelapi.kpkpo.com",
"https://novelapi-tn.kpkpo.com",
"https://novelapi-hw.tttxtt.com",
"https://novelapi-tn.tttxtt.com",
"https://novel-api.elklk.cn",
"https://novelapi.qwezxc4.cn",
"https://nov-api.chiyantu.com",
"https://novelapi.pvlmnez.cn"
        ]
    }
    setv(_);
}
uri = java.hexDecodeToString(result);
time = +java.timeFormatUTC(new Date(), 'yyyyMMdd', 8);
arr1 = []; // 成功
arr2 = []; // 失败
arr3 = []; // 新增
// 9x解密 & 笔趣阁解密
getResult = (host, path, run) => {
    url = String(host + path);
    if (url.match("#dns#")) {
        url = url.replace(
            /#dns#([\s\S]+)/,
            ($0, $1) => $1 + ',{"headers":{"Host":"gfnormal05at.com"}}'
        );
    }
    // java.log(url);
    try {
        Res = java.ajaxAll([url])[0];
        if (Res.code() == 200) {
            result = String(Res.body());
            try {
                JSON.parse(result);
            } catch (parse_err) {
                subStr = result.substring(3, result.length - 4);
                result = java.createSymmetricCrypto("DES/CBC/PKCS5Padding", "6CB1E21E", "1F0FB845").decryptStr(subStr);
            }
            cipher = java.createSymmetricCrypto("DESede/CBC/PKCS5Padding", "OW84U8Eerdb99rtsTXWSILDO", "SK8bncVu");
            result = String(result)
                .replace(/[^"]*[{}]{6,}([^"]+)/g, ($0, $1) => String(cipher.decryptStr($1))
                    .replace(/\n/g, '\\n')
                    .replace(/\r/g, '\\r')
                    .replace(/\f/g, '\\f')
                    .replace(/\t/g, '\\t')
                    .replace(/\"/g, '\\"')
                ).replace(/(\}|\])\s*,\s*(\}|\])/g, '}$1$2')
                .replace(/src="(.+?)"/g, 'src=\\"$1\\"');
            $ = JSON.parse(result).result;
            if (run) {
                arr2.length = arr2.length - 1;
                arr3 = arr3.concat($.hosts);
                return true;
            } else {
                return result;
            }
        } else {
            arr1.length = arr1.length - 1;
            return false;
        }
    } catch (err) {
        arr1.length = arr1.length - 1;
        return false;
    }
}
// 更新接口
verifyUrls = () => {
    try {
        for (host of _.url) {
            arr1.push(host);
            arr2.push(host);
            getResult(host, _path.GetHost, 1);
        }
        // 去重
        _.url = arr1.concat(arr3)
            .filter((value, index, self) => {
                return self.indexOf(value) == index && arr2.indexOf(value) == -1;
            });
        _.time = time
        setv(_);
        java.toast("接口校验成功");
    } catch (err) {
        java.toast("未知错误：" + err);
    }
}
// 加载 / 校验
if (_.time < time) {
    verifyUrls();
}
if (_.url[0]) {
    try {
        getResult(_.url[0], uri);
    } catch (err) {
        verifyUrls();
        getResult(_.url[0], uri);
    }
} else {
    java.toast("没有接口");
}

source.exploreUrl:
@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$$ = uri => `data:;base64,{{java.base64Encode(\`${uri}\`)}\},{"type":"${type}"}`;
$$ = (a, b, c) => {
    if (!a) return null;
    if (c) {
        uri = `rankList/${a}/0/${b}/${c}`;
    } else {
        uri = `tagsRankList/${a}/${b}`;
    }
    return $$$(`/cdn/category/${uri}/$\{page}.html`);
}
$arr1 = [
    ["推荐", "tuijian"],
    ["最新", "xinshu"],
    ["最热", "zuire"],
    ["完结", "wanjie"],
    ["评分", "pingfen"],
    ["收藏", "shoucang"]
];
$arr2 = [
    ["男", "1"],
    ["女", "2"]
];



push(`༺ˇ»\`ʚ首页ɞ´«ˇ༻`, null, 1);
push(`༺ 推荐 ༻`, null, 1);
[
    ["全网热搜", "hot"],
    ["人气精品", "vote", "fan"],
    ["最新更新", "new"],
    ["猜你喜欢", "like"]
].map([title, i] => {
    push(title, $$$(`/cdn/library/channelRankList/3/${i}/$\{page}.html`), 0.4);
});
[
    "推荐壹",
    "推荐貳",
    "大热榜",
    "月票榜"
].map((title, i) => {
    push(`[ ${title} ]`, $$$(`/api/library-channel?channel=${i+1}&page=$\{page}`), 0.4);
});
push("============  分割线  ============", null, 1);



push(`༺ˇ»\`ʚ排行ɞ´«ˇ༻`, null, 1);
[
    // ["周", "week"],
    // ["月", "month"],
    ["总", "all"]
].map([title, c] => {
    push(`༺ ${title}榜 ༻`, null, 1);
    $arr1.map([t2, b] => {
        $arr2.map([t1, a] => {
            push(`${t1}频${t2}榜`, $$(a, b, c), 0.4);
        });
    });
});
push("============  分割线  ============", null, 1);



list = [];
$arr2.map([t, i] => {
    result = java.hexEncodeToString(`/cdn/category/tags/${i}.html`);
    eval(String(source.bookSourceComment));
    list.push({
        name: `༺ ${t}频 ༻`,
        type: 1
    });
    for (i = 1; i < $.list.length; i++) {
        list = list.concat($.list[i].list);
    }
    list.push({
        name: "————"
    });
});
list.push({
    name: "============  分割线  ============",
    type: 1
});



// $arr1.slice(0, 4)
[$arr1[0]].map([title, $type] => {
    push(`༺ˇ»\`ʚ${title}ɞ´«ˇ༻`, null, 1);
    list.map($ => {
        if ($.name.length == 2)
            $.name += "小说";
        push($.name, $$($.id, $type), $.type || 0.25);
    });
});



JSON.stringify(sort);

